\label{thm:func}
Let $I\subseteq \mathbb R$ be a compact interval. Assume that $\mathbb F$ admits a density $f$ on $I$ satisfying $\|f\|_\infty<\infty$.
\begin{enumerate}
    \item Assume that $\mathbb E[H_-^{3d}]<\infty$. Let $Z(\cdot)$ be a centered Gaussian process on $I$ with covariance function $k(\cdot,\cdot)$. Then, in the Skorokhod topology, $\hat G_{n,*}(\cdot)\Rightarrow Z(\cdot)$.
    \item Assume that $\mathbb E[H_-^{m_0}]<\infty$ for some $m_0 > 11d/2$. Let $Z^{\mathsf V}(\cdot)$ be a centered Gaussian process on $I$ with covariance function $k^{\mathsf V}(\cdot,\cdot)$. Then, in the Skorokhod topology, $\hat G_{n,*}^{\mathsf V}(\cdot)\Rightarrow Z^{\mathsf V}(\cdot)$.
\end{enumerate}

\label{lem:truncated-cell-geometry}
For every \(t\geqslant h\),
\begin{equation}\label{eq:truncated-cell-identities}
\begin{aligned}
C_t(x;\varphi)
&=
\Big\{u\in B_{\sqrt{t-h}}(v):
L(x,u)\leqslant \inf_{y\in\varphi_{\leqslant t}}L(y,u)\Big\}
=C(x;\varphi)\cap B_{\sqrt{t-h}}(v).
\end{aligned}
\end{equation}
Consequently, \(C_t(x;\varphi)\subseteq C_{t'}(x;\varphi)\) whenever
\(t\leqslant t'\), and
\(
\bigcup_{t\in\mathbb R}C_t(x;\varphi)=C(x;\varphi).
\)

\label{rem:Qlb}
For any $x_0$ such that $\mathbb F((-\infty,x_0])>0$, and any $h\geqslant x_0$, we have
\begin{align*}
\mathbb Q(h)&\geqslant\kappa_d\int_{-\infty}^{x_0}((h-x_0)+(x_0-s))^{d/2}\mathbb F(\mathrm{d} s)\geqslant \kappa_d \mathbb F((-\infty,x_0])(h-x_0)^{d/2}.
\end{align*}
Note also that without loss of generality we may assume $x_0 \geqslant 0$.

On the event \(x\in\mathcal E(\mathcal P+\delta_x)\),
\eqref{eq:cell-at-cover-time} gives
\(
|C(x;\mathcal P+\delta_x)|
\leqslant \kappa_d\big(T(x;\mathcal P+\delta_x)-h\big)^{d/2}.
\)
Therefore, by Corollary~\ref{lem:cover-time-moment-integrability},
\begin{align*}
\mathbb E\Big[\mathbf{1}\{x\in\mathcal E(\mathcal P+\delta_x)\}
|C(x;\mathcal P+\delta_x)|^{4+p}\Big]
&\leqslant \kappa_d^{4+p}
\mathbb E\Big[\mathbf{1}\{x\in\mathcal E(\mathcal P+\delta_x)\}
\big(T(x;\mathcal P+\delta_x)-h\big)^{(4+p)d/2}\Big]\\
&\leqslant C\big(1+(z-h)_+^{(4+p)d/2}\big).
\end{align*}

\label{lem:t1}
Assume that $\mathbb E[H_-^{m_0}]<\infty$ for some
$m_0\geqslant(d+1)/2$. Then the following statements hold.
\medskip

(i) (\emph{Absolute integrability})
\begin{align*}
	\int_{-\infty}^z\int_{\mathbb R^{d,z'}}  \mathbf{1}\{L(x',0)<L((0,h),0)\}\mathbb Q(dx')\mathbb F(dh) < \infty;
\end{align*}

(ii) (\emph{Decay})
As $n\to\infty$,
\[
\int_{W_n^z}\int_{W_n^{\complement,z'}}
\mathbf{1}\{L(x',v)<L(x,v)\}\,\mathbb Q(dx')\mathbb Q(dx)
=O(|W_n|^{1-1/d}).
\]

\label{lem:weighted-deterministic-resampling}
For \(t>h\), the following assertions hold.
\begin{enumerate}
\item[\emph{(i)}]
The score \(A_x^{[t]}\) is measurable with respect to
\(\sigma(\mathcal P|_B)\)  with
\(A_x^{[t]}=A_x\) on \(\{T_x\leqslant t\}\).
For every \(p,a>0\), every fixed \(z\in\mathbb R\), and every \(h\leqslant z\),
\begin{equation}\label{eq:deterministic-truncation-error}
 \mathbb E[|A_x-A_x^{[t]}|^p]
 \leqslant
 C(t-h)^{-a}
 \big(1+(z-h)_+^{pd/2+a}\big).
\end{equation}

\item[\emph{(ii)}]
For every locally finite \(\mu\) and every
\(y\notin\mathscr D_x(\mu)\),
\(
 A(x;\mu+\delta_y)=A(x;\mu).
\)
When \(A(x;\mu)>0\), the cell and cover time are unchanged as well.

\item[\emph{(iii)}]
If \(\mathbb Q(B)<\infty\), then \(\mathcal P_x^{[t]}\) has the same law
as \(\mathcal P\), and
\begin{equation}\label{eq:deterministic-resampling-identity}
 \mathsf{Cov}(A_x^{[t]},A_{x'})
 =\mathbb E[
 (A_x^{[t]}-\mathbb E[A_x^{[t]}])
 \{A_{x'}-A_{x'}^{(x,t)}\}
 ].
\end{equation}
Furthermore,
\begin{equation}\label{eq:deterministic-resampling-change-probability}
 \mathbb P\big(A_{x'}\ne A_{x'}^{(x,t)}\big)
 \leqslant
 2\,\mathbb E[
 \mathbf{1}\{\mathcal E_{x'}\}\,
 \mathbb Q(B\cap D_{x'}^{\mathsf V})
 ].
\end{equation}
\end{enumerate}

\label{thm:KolBd}
	Assume that $\xi$ satisfies conditions (A0) -- (A2) and
	let $H$ be as in \eqref{eq:scoresum}. Then, for $p$ as in (A2) and
	$\tau:=p /(32+4 p)$, there exists a constant $C \in (0,\infty)$ depending only on $p$ such that
    $$
    \mathsf{Var}(H) \leqslant C \; \mathbb Q ((\kappa+g)^{2\tau}S).
    $$
    Moreover,
	\begin{align*}
		d_{W}\big(\frac{H-\mathbb E H}{\sqrt{\operatorname{Var} H}},  N\big) 
		&\leqslant C \Bigg[\frac{\sqrt{\mathbb Q f_\tau^2}}{\operatorname{Var} H}
		+\frac{\mathbb Q ((\kappa+g)^{2\tau}S)}{(\operatorname{Var} H)^{3/2}}\Bigg],
	\end{align*}
	and
	\begin{multline*}
		d_{K}\big(\frac{H-\mathbb E H}{\sqrt{\operatorname{Var} H}},
		N\big) 
		\leqslant C \Bigg[\frac{\sqrt{\mathbb Q f_\tau^2}
			+ \sqrt{\mathbb Q f_{2\tau}}}{\operatorname{Var} H}
		+\frac{\sqrt{\mathbb Q ((\kappa+g)^{2\tau}S)}}{\operatorname{Var} H}
		\\
		+\frac{\mathbb Q ((\kappa+g)^{2\tau} S)}{(\operatorname{Var} H)^{3/2}} +\frac{(\mathbb Q ((\kappa+g)^{2\tau} S))^{5/4}
			+ (\mathbb Q ((\kappa+g)^{2\tau} S))^{3/2}}{(\operatorname{Var} H)^2}\Bigg],
	\end{multline*}
	where $N$ is a standard normal random variable and
	$C \in (0,\infty)$ is a constant depending only on $p$.

\label{thm:multclt}

Let $\mathbb Q = \lambda \otimes \mathbb{F}$ be a \(\sigma\)-finite measure on $\mathbb R^{d+1}$ and \(\mathcal P\) be a Poisson process on $\mathbb R^{d+1}$ with intensity measure $\mathbb Q$ as in Theorem \ref{thm:mult}. 
For $m \geqslant 1$, let $F=(F_1,\ldots,F_m)$ be an $\mathbb R^m$-valued random vector such that \(F_i \in \operatorname{dom} D\) and \(\mathbb E F_i=0\) for all \(i \in [m]\). Let \(\Sigma=(\sigma_{ij})_{i,j \in [m]}\) be a symmetric positive semidefinite matrix and let \(X \sim \mathcal N(0,\Sigma)\). Then for all \(q_1,q_2 \in [1,2]\),
\[
d_3(F,X) \leqslant \frac{1}{2}\big(\zeta_1+\zeta_2^{(q_1)}+\zeta_3^{(q_1)}\big)+\zeta_4^{(q_2)},
\]
where
\begin{align}
\zeta_1 &:= \sum_{i,j=1}^m \big|\sigma_{ij}-\mathsf{Cov}(F_i,F_j)\big|, \label{eq:zetas_mult_1}\\
\zeta_2^{(q_1)}
&:= 2^{2/q_1-1}\sum_{i,j=1}^m
\Bigg(
\int_{\mathbb R^{d+1}}
\Bigg(
\int_{\mathbb R^{d+1}}
\mathbb E\big[|D^{(2)}_{x,y}F_i|^{2q_1}\big]^{1/(2q_1)}
\mathbb E\big[|D^{(2)}_{x,y}F_j|^{2q_1}\big]^{1/(2q_1)}
\,\mathbb Q(\mathrm{d} x)
\Bigg)^{q_1}
\mathbb Q(\mathrm{d} y)
\Bigg)^{1/q_1}, \label{eq:zetas_mult_2}\\
\zeta_3^{(q_1)}
&:= 2^{2/q_1}\sum_{i,j=1}^m
\Bigg(
\int_{\mathbb R^{d+1}}
\Bigg(
\int_{\mathbb R^{d+1}}
\mathbb E\big[|D_xF_i|^{2q_1}\big]^{1/(2q_1)}
\mathbb E\big[|D^{(2)}_{x,y}F_j|^{2q_1}\big]^{1/(2q_1)}
\,\mathbb Q(\mathrm{d} x)
\Bigg)^{q_1}
\mathbb Q(\mathrm{d} y)
\Bigg)^{1/q_1}, \label{eq:zetas_mult_3}\\
\zeta_4^{(q_2)}
&:= m^{q_2-1}\sum_{i,j=1}^m
\int_{\mathbb R^{d+1}}
\mathbb E\big[|D_xF_i|^{q_2+1}\big]^{1/(q_2+1)}
\mathbb E\big[|D_xF_j|^{q_2+1}\big]^{1-1/(q_2+1)}
\,\mathbb Q(\mathrm{d} x). \label{eq:zetas_mult_4}
\end{align}

\label{pr:cum}
Assume \(\mathbb E[H_-^{3d}]<\infty\). Then
\(
 \sup_{n\geqslant1}\sup_{I\subseteq J}
 |W_n|^{-1}|c_4(G_n(I))|<\infty.
\)

\label{lem:lattice-shell-estimate}
Let \(z\in\mathbb Z^d\). Then,
\(
 \#\{z'\in\mathbb Z^d:m\leqslant\|z-z'\|<m+1\}
	\in O(m^{d-1}).
\)

\label{pr:varV}
Under the standing assumptions of Section~\ref{sec:tight_V}, we have
\(
\sup_{n\geqslant1}\sup_{I=(s,t]\subseteq J}
\mathsf{Var}(G_n^{\mathsf V}(I))/(|W_n||I|)< \infty.
\)

\label{lem:weighted-spatial-truncation}
Let \(\mathcal A\) be a set of at most three cube indices, and let \(X_{\mathcal A}\) be a centered product of at most three centered variables of the form \(\Delta_i^{\mathsf V}(I)-\mathbb E[\Delta_i^{\mathsf V}(I)]\), with \(i\in\mathcal A\). Let \(\mathcal F_{\mathcal A}(r):=\sigma(\mathcal P|_{S_r(\mathcal A)})\) and \(X_{\mathcal A}^{(r)}:=\mathbb E[X_{\mathcal A}\mid \mathcal F_{\mathcal A}(r)]\). Then,
\[
 \sup_{n,I,\mathcal A}
 \|X_{\mathcal A}-X_{\mathcal A}^{(r)}\|_{a_0}
 \in O\big((1+r)^{-3d-1}\big).
\]

\label{lem:qbound}
	Assume $\mathbb E[H_-^{md}]<\infty$.	There exists a constant $c > 0$ such that $q(x_1, x_2)$ satisfies
	\begin{equation*}
		q(x_1, x_2) \lesssim \big( 1 + h_{1,-}^{d/2} + h_{2,-}^{d/2}\big)  \mathbf{1}\{A \leqslant 2x_0\}  + [(1+A)^{-(m-1/2)d} + \exp(-c A^{d/2})] \mathbf{1}\{A >0\}.
	\end{equation*}

Recall that $q(x_1, x_2) = \int_{W_n^z} \mathbb{P}(\{x_1, x_2\} \subseteq D^{\mathsf V}(x_3, T_3)) \mathbb Q(d x_3)$, where we write $T_3 \equiv T(x_3, \mathcal{P}+ \delta_{x_3})$ for notational simplicity. As noted in \eqref{eq:tailbd}, for $x_1$ and $x_2$ to be covered, the cover time $T_3$ must satisfy
	\begin{equation*}
		T_3 \geqslant \frac{1}{8}\|v_1-v_3\|^2 + ({h_1 + h_3})/{2} \quad \text{and} \quad T_3 \geqslant \frac{1}{8}\|v_2-v_3\|^2 + (h_2 + h_3)/{2}.
	\end{equation*}
	Since $v_3 \in W_n$, we have $\|v_i-v_3\|^2 \geqslant d(v_i, W_n)^2$ for $i \in \{1, 2\}$. Decompose for $i \in \{1,2\}$,
	\begin{align*}
		\frac{1}{8}\|v_i-v_3\|^2 &\geqslant \frac{1}{16}\|v_i-v_3\|^2 + \frac{1}{32}d(v_i, W_n)^2 + \frac{1}{32}\|v_i-v_3\|^2.
	\end{align*}
	Substituting these into the bounds for $T_3$ and taking their arithmetic mean yields
	\begin{equation*}
		T_3 \geqslant \frac{1}{32}\|v_1-v_3\|^2 + \frac{1}{32}\|v_2-v_3\|^2 + \frac{1}{64}d(v_1, W_n)^2 + \frac{1}{64}d(v_2, W_n)^2 + \frac{1}{64}\|v_1-v_3\|^2 + \frac{1}{64}\|v_2-v_3\|^2 + \frac{h_1+h_2+2h_3}{4}.
	\end{equation*}
	Applying the geometric triangle inequality $\frac{1}{64}\|v_1-v_3\|^2 + \frac{1}{64}\|v_2-v_3\|^2 \geqslant \frac{1}{128}\|v_1-v_2\|^2$, and dropping $\frac{1}{32}\|v_2-v_3\|^2 + \frac{1}{64}d(v_1, W_n)^2\geqslant 0$, we obtain
	\begin{equation*}
		T_3 \geqslant \frac{1}{32}\|v_1-v_3\|^2 + \underbrace{ \frac{1}{128}\|v_1-v_2\|^2                              
			+ \frac{1}{64}d(v_2, W_n)^2 + \frac{h_1+h_2}{4} }_{2 A(x_1, x_2)} + \frac{h_3}{2}.
	\end{equation*}
	Since the event $\{\{x_1, x_2\} \subseteq D^{\mathsf V}(x_3, T_3)\}$ also forces $T_3 >h_3$, using the exponential tail bound in Proposition \ref{prop:CoverTimetail}(iii), we obtain
	\begin{equation*}
		q(x_1, x_2) \leqslant \int_{\mathbb{R}^{d, z}} \exp\big(-\frac{1}{2^d}\mathbb{Q}\big( \frac{1}{64}\|v_1-v_3\|^2 + A(x_1, x_2) + \frac{3h_3}{4} \big)\big) \mathbb Q(dx_3).
	\end{equation*}
	Further denote $K = A(x_1, x_2) + {3h_3}/{4}$. We first evaluate the inner spatial integral over $v_3 \in \mathbb{R}^d$:
	\begin{equation*}
		J(K) := \int_{\mathbb{R}^d} \exp\big(-\frac{1}{2^d}\mathbb{Q}\big(\frac{1}{64}\|v_1-v_3\|^2 + K\big)\big) \,dv_3.
	\end{equation*}
	Applying the substitution $y = (v_1-v_3)/\sqrt{32}$ (which implies $dv_3 \asymp dy$), we partition the integration domain into regions $U_1 = \{ \|y\|^2 + K \leqslant x_0 \}$ and $U_2 = \{ \|y\|^2 + K > x_0 \}$. Integrating over $U_1$ yields
	\begin{equation*}
		\int_{U_1} \exp\big(-\frac{1}{2}\mathbb{Q}(\|y\|^2 + K)\big) \,dy \leqslant \int_{\|y\|^2 \leqslant (x_0 - K)_+} 1 \, dy = \kappa_d (x_0 - K)_+^{d/2}.
	\end{equation*}
	On $U_2$, the argument exceeds $x_0$, so that the polynomial lower bound $\mathbb{Q}(u) \geqslant \tilde{c} u^{d/2}$ applies by Remark \ref{rem:Qlb}.
	\begin{itemize}
		\item \textbf{Case 1 ($K \geqslant 0$):} In this case, we have $K = K_+$ and thus
		\begin{equation*}
			\int_{U_2} \exp\big(-\frac{\tilde{c}}{2}(\|y\|^2 + K)^{d/2}\big) \,dy \leqslant \exp(-c K_+^{d/2}) \int_{\mathbb{R}^d} \exp(-c \|y\|^d) dy \lesssim \exp(-c K_+^{d/2}).
		\end{equation*}
		\item \textbf{Case 2 ($K < 0$):} Here we apply the substitution $u = \|y\|^2 + K$. The domain is $u > x_0$, and the radial measure transforms to $dy \propto (u + |K|)^{(d-2)/2} du$. Since $(u+|K|)^{(d-2)/2} \lesssim (u^{(d-2)/2} + |K|^{(d-2)/2})$, integrating against $\exp(-\frac{\tilde{c}}{2}u^{d/2})$ yields
		\(
			\int_{U_2} \exp\big(-\frac{\tilde{c}}{2}u^{d/2}\big) \, dy \lesssim 1+ |K|^{(d-2)/2} \lesssim (x_0 - K)_+^{d/2}.
		\)
	\end{itemize}
	Summing the bounds yields 
	\begin{equation}\label{eq:J}
		J(K) \leqslant C \big( (x_0 - K)_+^{d/2} + \exp(-c K_+^{d/2}) \big).
	\end{equation}

	Finally, we integrate $J(K) =J(A(x_1, x_2) + \frac{3h_3}{4})$ over $h_3 \in (-\infty, z]$ with respect to $h_3$ to obtain a bound on $q(x_1,x_2)$. Writing $A\equiv A(x_1,x_2)$, for the first summand in \eqref{eq:J}, we must evaluate the integral
	\begin{equation*}
		I_{cut}(A) := \int_{-\infty}^z \big(x_0 - A - \frac{3h_3}{4}\big)_+^{d/2} \,\mathbb F(dh_3) \leqslant \int_{-\infty}^z \big(x_0 - A + \frac{3}{4}h_{3,-}\big)_+^{d/2} \,\mathbb F(dh_3).
	\end{equation*}
	Note that the integrand is zero unless $\frac{3}{4}h_{3,-} > A - x_0$.

	\begin{itemize}
			\item \textbf{Case 1 ($A \leqslant 2x_0$):} 
			Noting $-A \leqslant \frac{1}{8}h_{1,-} + \frac{1}{8}h_{2,-}$ and using subadditivity, we bound the integral
			\begin{align*}
				I_{cut}(A) \mathbf{1}\{A \leqslant 2x_0\} &\leqslant \mathbf{1}\{A \leqslant 2x_0\} \int_{-\infty}^z \big( x_0 + \frac{1}{8}h_{1,-} + \frac{1}{8}h_{2,-} + \frac{3}{4}h_{3,-} \big)^{d/2} \,\mathbb F(dh_3)\\
				&\leqslant C \mathbf{1}\{A \leqslant 2x_0\} \big( 1 + h_{1,-}^{d/2} + h_{2,-}^{d/2}\big).
			\end{align*}

		\item \textbf{Case 2 ($A > 2x_0$):} 
		Since $A > 2x_0$, we have $A - x_0 > {A}/{2}$. Thus, the integrand in $I_{cut}(A)$ is non-zero only if $\frac{3}{4}h_{3,-} > {A}/{2}$. On this restricted domain, dropping $x_0 - A \leqslant 0$ term, and integrating yields
		\begin{equation*}
			I_{cut}(A) \mathbf{1}\{A > 2x_0\} \leqslant \int_{-\infty}^{-\frac{2A}{3}} \big( \frac{3}{4}h_{3,-} \big)^{d/2} \mathbb F(dh_3) \leqslant C \min\{\mathbb E H_-^{d/2},A^{-(m-1/2) d} \mathbb E H_-^{m d}\} \in O((1+A)^{-(m-1/2) d}).
		\end{equation*}
	\end{itemize}
	Thus,
	\begin{equation*}
		I_{cut}(A) \leqslant C \big( 1 + h_{1,-}^{d/2} + h_{2,-}^{d/2}\big)\mathbf{1}\{A \leqslant 2x_0\} + C(1+A)^{-(m-1/2) d} \mathbf{1}\{A > 2x_0\}.
	\end{equation*}

	Finally, we consider the exponential tail term in \eqref{eq:J}. If $A \leqslant 0$, we  trivially bound the exponential by $1$. If $A > 0$, we partition the integration domain for $h_3$:
	\begin{itemize}
		\item \textbf{Case 1 $\big( 3h_{3,-} \leqslant 2{A} \big)$:} Here, $A + \frac{3h_3}{4} \geqslant {A}/{2}$. The exponential is thus bounded by $\exp(-c (A/2)^{d/2})$. Integrating over $h_3$ thus yields a bound $\exp(-c' A^{d/2})$ for some $c'>0$.
		\item \textbf{Case 2 $\big( {3}h_{3,-} > 2{A} \big)$:} In this case, we bound the exponential term by $1$. By Markov's inequality and our assumed $md$ finite moments for $H_-$,
		\begin{equation*}
			\mathbb{P}\big( H_- > {2A}/{3} \big) \lesssim \min\{1,A^{-m d} \mathbb{E}[H_-^{m d}]\} \lesssim (1+A)^{-md}.
		\end{equation*}
	\end{itemize}

	Summing the different bounds and noting $x_0 \geqslant 0$, we obtain
	\begin{align*}
		q(x_1, x_2) &\leqslant C \big( 1 + h_{1,-}^{d/2} + h_{2,-}^{d/2}\big)\mathbf{1}\{A \leqslant 2x_0\} + (1+A)^{-(m-1/2)d} \mathbf{1}\{A > 2x_0\} \\
		& \qquad \qquad + \mathbf{1}\{A \leqslant 0\} + [\exp(-c' A^{d/2}) + (1+A)^{-md}]\mathbf{1}\{A >0\} \\
		& \leqslant C  \big( 1 + h_{1,-}^{d/2} + h_{2,-}^{d/2}\big)\mathbf{1}\{A \leqslant 2x_0\}  + [(1+A)^{-(m-1/2) d} + \exp(-c' A^{d/2})] \mathbf{1}\{A >0\},
	\end{align*}
	completing the proof.

\label{lem:BM55ext}
For $H$ as in Theorem \ref{thm:KolBd}, assume that conditions {\rm (A1)} and {\rm (A2)} hold. Set
\(
    r_p:=4+p/2
\) and \(
    k_p:=4+\lceil p/2\rceil
\).
Let $g$ and $h$ be defined as in \eqref{eq:g}. Then there exists a constant $C_p\in(0,\infty)$, depending
only on $p$, such that, for every $y\in\mathbb R^{d+1}$ and every
$\mu\in\mathbf N$ with $\mu(\mathbb R^{d+1})\leqslant1$,
\begin{equation}
\label{eq:BM55ext}
    \mathbb E\big|D_yH(\mathcal P+\mu)\big|^{r_p}
    \leqslant
    C_p\left[
        M_p(y)^{r_p}
        +
        h(y)\big(1+g(y)^{k_p-1}\big)
    \right].
\end{equation}
In particular, with $S$ defined in \eqref{eq:g}, there exists a constant $C_p'\in(0,\infty)$, depending
only on $p$ such that
\begin{equation}
\label{eq:BM55extS}
    \mathbb E\big|D_yH(\mathcal P+\mu)\big|^{r_p}
    \leqslant C_p' S(y)^{r_p/4}.
\end{equation}

\label{lem:weighted-inserted-palm-moment}
For every \(\gamma>0\),
\[
 \sup_{x=(v,h):\,h\in J}
 \mathbb E\left[
 \mathbf{1}\{x\in\mathcal E(\mathcal P+\delta_x)\}
 \bigl(1+((b\vee T(x;\mathcal P+\delta_x))-a)_+\bigr)^\gamma
 \right]<\infty.
\]
